const int ART_WIDTH[SCALES]={12,18,24,32,42,54,68,84,104,128};
uint8_t rgb(int r,int g,int b){return uint8_t(192+r+4*g+16*b);}
RGB888 colour(uint8_t c){return RGB888((c&3)*85,((c>>2)&3)*85,((c>>4)&3)*85);}
void rect(int x,int y,int x2,int y2,uint8_t c){if(sceneDrawing){x=std::max(viewLeft(),x);x2=std::min(viewRight(),x2);y=std::max(28,y);y2=std::min(191,y2);}if(x2<0||x>639||y2<0||y>199||x2<x||y2<y)return;x=std::max(0,x);x2=std::min(639,x2);y=std::max(0,y);y2=std::min(199,y2);if(rasterActive){rasterRect(x,y,x2-x+1,y2-y+1,c);return;}canvas.setBrushColor(colour(c));canvas.fillRectangle(x,y,x2,y2);}
void text(int x,int y,const char*s,uint8_t c=255){if(rasterActive){rasterText(x,y,s,c);return;}canvas.selectFont(&FONT_8x8);canvas.setPenColor(colour(c));canvas.drawText(x,y,s);}
void centred(int y,const char*s,uint8_t c=255){text((640-int(strlen(s))*8)/2,y,s,c);}
void hideActors(){for(int i=0;i<=MAX_ACTORS;++i)actors[i].visible=false;}
void initGraphics(){for(int i=0;i<PROP_FRAMES;++i)actorFrames[i]=&bmpProp[i];for(int i=0;i<40;++i)actorFrames[i+PROP_FRAMES]=&bmpTraffic[i];for(int i=0;i<18;++i)playerFrames[i]=&bmpPlayer[i];hideActors();}
void buildRoadRows(){float grade=(heightAt(race.z+16)-heightAt(race.z-16))/32;horizon=int(limit(72+grade*60,62,82));for(int y=0;y<200;++y)roadRows[y]={320,8,2000};int last=horizon-1;Projection old=project(1100);
 for(int step=0;step<160&&last<199;++step){float dist=8000.0f/(step+8);Projection p=project(dist);int end=int(p.y);if(end<=last)continue;end=std::min(end,199);int from=last+1;for(int y=std::max(horizon,from);y<=end;++y){float t=float(y-from+1)/std::max(1,end-from+1);roadRows[y]={old.x+(p.x-old.x)*t,old.w+(p.w-old.w)*t,old.dist+(p.dist-old.dist)*t};}last=end;old=p;}
 for(int y=std::max(horizon,last+1);y<200;++y)roadRows[y]={old.x,old.w,old.dist};}
void renderRoad(){buildRoadRows();rasterRoad=sceneDrawing=true;}
int scaleFrame(float desired){int best=0;for(int i=1;i<SCALES;++i)if(fabsf(ART_WIDTH[i]-desired)<fabsf(ART_WIDTH[best]-desired))best=i;return best;}
bool visibleOnRoad(const Projection&p){int y=int(p.y);return y>=horizon&&y<199&&p.dist<=roadRows[y].dist+35;}
void addActor(float distance,float lane,int type,bool car){if(distance<54||distance>1050||drawCount>=64)return;Projection p=project(distance,lane);if(!visibleOnRoad(p))return;float desired=(car?300.0f:360.0f)*p.w/900;int f=scaleFrame(desired);Bitmap*b=car?&bmpTraffic[type*10+f]:&bmpProp[currentStage()*40+type*10+f];int x=int(p.x)-b->width/2,y=int(p.y)-b->height;if(x+b->width<0||x>=640||y<27||y+b->height>=200)return;drawList[drawCount++]={distance,(car?PROP_FRAMES:currentStage()*40)+type*10+f,x,y};}
void renderGate(){float z=race.checkpoint<CHECKPOINT_COUNT?CHECKPOINTS[race.checkpoint]:FINISH_Z;float distance=z-race.z;if(distance<55||distance>950)return;Projection p=project(distance);if(!visibleOnRoad(p))return;int x1=int(p.x-p.w*.95f),x2=int(p.x+p.w*.95f),bottom=int(p.y),top=bottom-int(180*p.w/900);int thickness=std::max(2,int(p.w*.025f));rect(x1,top,x1+thickness,bottom,255);rect(x2-thickness,top,x2,bottom,255);rect(x1,top,x2,top+10,rgb(0,1,2));for(int x=x1;x<x2;x+=12)rect(x,top+10,x+5,top+12,255);const char*label=race.checkpoint<CHECKPOINT_COUNT?"CHECKPOINT":"META";if(x2-x1>int(strlen(label))*8+8)text(int(p.x)-int(strlen(label))*4,top+1,label);}
void renderActors(const Input&in){hideActors();drawCount=0;float spacing=liteMode?180.0f:140.0f;int start=int(race.z/spacing);for(int i=start;i<start+(liteMode?6:8);++i){float z=i*spacing+90;addActor(z-race.z,-1.65f,0,false);addActor(z+42-race.z,1.65f,i%5==3?3:0,false);if(i%8==4)addActor(z+72-race.z,2.2f,2,false);if(i%7==1)addActor(z+60-race.z,-2.1f,1,false);}
 for(int i=0;i<TRAFFIC_COUNT;++i){Traffic&t=race.traffic[i];addActor(t.z-race.z,t.lane,t.type,true);}std::sort(drawList,drawList+drawCount,[](const Actor&a,const Actor&b){return a.distance>b.distance;});int first=std::max(0,drawCount-(liteMode?10:16));for(int i=first;i<drawCount;++i){Actor&a=drawList[i];blit(a.x,a.y,actorFrames[a.frame]);}
 int turn=in.right&&!in.left?2:in.left&&!in.right?0:1;if(race.crash>0)turn=(frameCount/4)%2?0:2;int frame=CAR_FIRST_FRAME[race.car]+(race.car==2?turn*2+(race.speed>20?int(frameCount/5)%2:0):turn);int x=(wideView?232:250)+int(race.x*(wideView?35:28)),y=(wideView?140:144)+(race.offroad>0?int(frameCount%3)-1:0);blit(x,y,wideView?playerFrames[frame]:&bmpPlayerSmall[frame]);if(in.brake){float scale=wideView?1.0f:140.0f/176;const int lampX[5][2]={{33,135},{49,126},{27,148},{35,133},{34,136}};int yy=race.car==1?37:race.car==2?33:33;for(int side=0;side<2;++side){int xx=x+int(lampX[race.car][side]*scale);rect(xx,y+int(yy*(wideView?1.0f:46.0f/52)),xx+std::max(3,int(10*scale)),y+int(yy*(wideView?1.0f:46.0f/52))+2,rgb(3,1,1));}}
}
void digits(int x,int y,int n,int count){int divis=1;for(int k=1;k<count;++k)divis*=10;for(int k=0;k<count;++k){blit(x+18*k,y,&bmpDigit[(n/divis)%10]);if(divis>1)divis/=10;}}
uint8_t mapPixels[64*88];Bitmap mapBitmap(64,88,mapPixels,PixelFormat::RGBA2222);int mapStage=-1,mapPassed=-1,lastMapX=-1,lastMapY=-1;int mapX[41],mapY[41];
void mapPixel(int x,int y,uint8_t c){if(x>=0&&x<64&&y>=0&&y<88)mapPixels[y*64+x]=c;}
void mapLine(int x0,int y0,int x1,int y1,uint8_t c,int radius){int dx=abs(x1-x0),dy=-abs(y1-y0),sx=x0<x1?1:-1,sy=y0<y1?1:-1,err=dx+dy;for(;;){for(int y=-radius;y<=radius;++y)for(int x=-radius;x<=radius;++x)mapPixel(x0+x,y0+y,c);if(x0==x1&&y0==y1)break;int e=2*err;if(e>=dy){err+=dy;x0+=sx;}if(e<=dx){err+=dx;y0+=sy;}}}
void renderStageMap(){int stage=currentStage();float local=limit(race.z-stage*STAGE_LENGTH,0,STAGE_LENGTH);int passed=local>=4200?2:local>=2100?1:0;
 if(stage!=mapStage||passed!=mapPassed){float lo=1e9f,hi=-1e9f;for(int i=0;i<=40;++i){float v=centreAt(stage*STAGE_LENGTH+i*160);lo=std::min(lo,v);hi=std::max(hi,v);}memset(mapPixels,192,sizeof(mapPixels));for(int i=0;i<=40;++i){mapX[i]=10+int((centreAt(stage*STAGE_LENGTH+i*160)-lo)/std::max(1.0f,hi-lo)*42);mapY[i]=3+i*2;}
  for(int i=1;i<=40;++i)mapLine(mapX[i-1],mapY[i-1],mapX[i],mapY[i],213,2);for(int i=1;i<=40;++i)mapLine(mapX[i-1],mapY[i-1],mapX[i],mapY[i],234,0);
  for(int n=0;n<3;++n){int at=n==0?13:n==1?26:40;for(int y=-2;y<=2;++y)for(int x=-2;x<=2;++x)mapPixel(mapX[at]+x,mapY[at]+y,n<passed?204:207);}
  mapStage=stage;mapPassed=passed;mapDirty=true;}
 float f=local/160;int a=std::min(39,int(f));float t=f-a;int x=int(mapX[a]+(mapX[a+1]-mapX[a])*t),y=int(mapY[a]+(mapY[a+1]-mapY[a])*t);if(x!=lastMapX||y!=lastMapY){mapDirty=true;lastMapX=x;lastMapY=y;}
 text(16,31,"MAPA",rgb(3,3,1));blit(0,42,&mapBitmap);rect(x-3,42+y-2,x+3,42+y+2,255);rect(x-1,42+y-1,x+1,42+y+1,rgb(3,0,0));}
